<script lang="ts" module>import type {RxColor} from '$lib/registry/lib/color';export interface TickRailProps{value?:number;min?:number;max?:number;step?:number;color?:RxColor;orientation?:'horizontal'|'vertical';formatValue?:(value:number)=>string;onValueChange?:(value:number)=>void}</script>
<script lang="ts">import {styleColor} from '$lib/registry/lib/color';let{value=$bindable(0),min=0,max=100,step=1,color,orientation='horizontal',formatValue=(n)=>String(n),onValueChange}:TickRailProps=$props();const low=$derived(Math.min(min,max)),high=$derived(Math.max(min,max)),safeStep=$derived(step>0?step:1),normalized=$derived(Math.min(high,Math.max(low,low+Math.round((value-low)/safeStep)*safeStep)));const tickCount=$derived(Math.min(101,Math.floor((high-low)/safeStep)+1));$effect(()=>{if(value!==normalized)value=normalized});function input(e:Event){value=Number((e.currentTarget as HTMLInputElement).value);onValueChange?.(value)}</script>
<label class="rx-tick-rail rx-tick-rail--{orientation}" style={styleColor(color)??'--rx-color:var(--rx-primary)'}><span class="rx-tick-rail__value">{formatValue(normalized)}</span><input type="range" value={normalized} min={low} max={high} step={safeStep} aria-orientation={orientation} aria-valuetext={formatValue(normalized)} oninput={input}/><span class="rx-tick-rail__ticks" aria-hidden="true" style={`--rx-ticks:${tickCount}`}></span></label>
<style>.rx-tick-rail{position:relative;display:grid;gap:.5rem;width:100%;min-width:10rem}.rx-tick-rail__value{color:rgb(var(--rx-color));font-size:.78rem;font-weight:700}.rx-tick-rail input{width:100%;accent-color:rgb(var(--rx-color))}.rx-tick-rail__ticks{height:.45rem;background:repeating-linear-gradient(90deg,rgb(var(--rx-text)/.25) 0 1px,transparent 1px calc(100% / max(1,var(--rx-ticks) - 1)))}.rx-tick-rail--vertical{width:max-content;min-width:0;height:14rem}.rx-tick-rail--vertical input{width:14rem;transform:rotate(-90deg);transform-origin:top left;translate:0 14rem}.rx-tick-rail--vertical .rx-tick-rail__ticks{display:none}</style>
